# Reproducible validation; never silently stretch a polity's lifetime to fit a link.
base=json.loads((root/'dist/data/history.json').read_text());by_id={n['id']:n for n in base['cultures']+nodes}
assert len(by_id)==len(base['cultures'])+len(nodes),'duplicate node'
assert len({r['id'] for r in base['relations']+relations})==len(base['relations'])+len(relations),'duplicate relation'
for r in relations:
 assert r['start']<=r['end'] and r['start']!=0 and r['end']!=0,r['id']
 for id in [r['from'],r['to']]:
  n=by_id[id];assert n['start']<=r['start']<=r['end']<=n['end'],(r['id'],id)
 for src in r['sources']:assert src in sources or src in base['sources'],src
used={id for r in relations for id in [r['from'],r['to']]}
# Unused research candidates are not shipped as empty nodes.
nodes=[n for n in nodes if n['id'] in used]
for n in nodes:
 assert len(n['summary'])>25 and n['sources'],n['id']
 for src in n['sources']:assert src in sources or src in base['sources'],src
out={'schemaVersion':1,'title':'Исторические связи: обмен, власть, знания и договоры','coverage':'Отдельные подтверждённые примеры разных эпох, не исчерпывающая карта всех отношений. Интервалы обобщают свидетельства и не означают ежегодного непрерывного обмена.','nodes':nodes,'relations':relations,'sources':sources}
(root/'dist/data/relation-atlas.json').write_text(json.dumps(out,ensure_ascii=False,indent=1)+'\n')
print(f"{len(nodes)} additional nodes, {len(relations)} additional relations, {len(relations)+len(base['relations'])} total relations")
